func getMaxGridHappiness(m int,n int,introvertsCount int,extrovertsCount int)int{I,E:=introvertsCount,extrovertsCount;if n>m{m,n=n,m};k:=1;for j:=0;j<n;j++{k*=3};h:=make([]int,k);ii:=make([]int,k);ee:=make([]int,k);for x:=0;x<k;x++{a,p:=x,0;for j:=0;j<n;j++{d:=a%3;a/=3;if d==1{h[x]+=120;ii[x]++}else if d==2{h[x]+=40;ee[x]++};if d>0&&p>0{if d==1{h[x]-=30}else{h[x]+=20};if p==1{h[x]-=30}else{h[x]+=20}};p=d}};mem:=map[[4]int]int{};var f func(int,int,int,int)int;f=func(r,i,e,p int)int{if r==m{return 0};q:=[4]int{r,i,e,p};if v,ok:=mem[q];ok{return v};z:=0;for c:=0;c<k;c++{if ii[c]<=i&&ee[c]<=e{a,b,s:=p,c,0;for j:=0;j<n;j++{u,d:=a%3,b%3;a/=3;b/=3;if u>0&&d>0{if u==1{s-=30}else{s+=20};if d==1{s-=30}else{s+=20}}};v:=h[c]+s+f(r+1,i-ii[c],e-ee[c],c);if v>z{z=v}}};mem[q]=z;return z};return f(0,I,E,0)}
